# Aplica los cambios de Ferremovil (productos, ventas, lector y crear producto al escanear).
# Uso: guarda este archivo dentro de la carpeta ferremovil-app y ejecutalo asi:
#   powershell -ExecutionPolicy Bypass -File .\aplicar-ferremovil.ps1
# Antes de sobrescribir, guarda una copia de cada archivo en una carpeta _respaldo_...

$ErrorActionPreference = 'Stop'

$raiz = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }
$paquete = Join-Path $raiz 'package.json'

if (-not (Test-Path $paquete) -or -not (Select-String -Path $paquete -Pattern '"name"\s*:\s*"ferremovil-app"' -Quiet)) {
    Write-Host 'Este script debe estar dentro de la carpeta ferremovil-app (donde esta package.json).' -ForegroundColor Red
    exit 1
}

$respaldo = Join-Path $raiz ('_respaldo_' + (Get-Date -Format 'yyyyMMdd-HHmmss'))

$archivos = @(
    @{ Ruta = 'src/lib/api.ts'; Datos = '' },
    @{ Ruta = 'src/lib/formato.ts'; Datos = '' },
    @{ Ruta = 'src/components/EscanerCodigo.tsx'; Datos = '' },
    @{ Ruta = 'src/components/Navegacion.tsx'; Datos = '' },
    @{ Ruta = 'src/components/FormularioProducto.tsx'; Datos = '' },
    @{ Ruta = 'src/app/ferremovil.css'; Datos = '' },
    @{ Ruta = 'src/app/layout.tsx'; Datos = '' },
    @{ Ruta = 'src/app/productos/page.tsx'; Datos = '' },
    @{ Ruta = 'src/app/dashboard/page.tsx'; Datos = '' }
)

foreach ($archivo in $archivos) {
    $destino = Join-Path $raiz ($archivo.Ruta -replace '/', '\')
    $carpeta = Split-Path $destino -Parent

    if (-not (Test-Path $carpeta)) {
        New-Item -ItemType Directory -Path $carpeta -Force | Out-Null
    }

    if (Test-Path $destino) {
        $copia = Join-Path $respaldo ($archivo.Ruta -replace '/', '\')
        New-Item -ItemType Directory -Path (Split-Path $copia -Parent) -Force | Out-Null
        Copy-Item -Path $destino -Destination $copia -Force
    }

    [System.IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String($archivo.Datos))
    Write-Host ('OK  ' + $archivo.Ruta) -ForegroundColor Green
}

Write-Host ''
Write-Host 'Listo. Archivos escritos:' $archivos.Count -ForegroundColor Green
if (Test-Path $respaldo) {
    Write-Host ('Copia de los archivos anteriores en: ' + $respaldo)
}
Write-Host 'Ahora corre:  npm run build   (o  npm run dev)'
